import 'bootstrap/dist/css/bootstrap.min.css'
imp
import './App.css'
import { useState,useEffect } from 'react'; // Step 1: import useStart and useEffect
import Axios from 'axios';

function App() {
  const API = "http://localhost:3001/";
  //useState
const [users, setUsers] = useState([]); // Step 2 create useStatect
const [name,setName] = useState("");
const [age,setAge] = useState();
const [email,setEmail] = useState("");
useEffect(()=>{                         // Step 3 create useEffect & copy Axios insed useEffect
Axios.get(`${API}`)
 .then(res=>{
  setUsers(res.data); // Display the setUsers for useState
 });
},[users]);

const createUser=()=>{
  if(name&& age&& email){
 Axios.post(`${API}createUser`, {name, age, email})
  .then(res=>console.log(res.data))
  }
}



  return (
    <div className="card">
      {users.map(user=>{
      return(
        <ul>
          <li>Name:{user.name}</li>
          <li>Age:{user.age}</li>
          <li>Email:{user.email}</li>
        </ul>
      );
 })}
    <div>
      <input type="text" placeholder='Name'onChange={e=>setName(e.target.value)} />
      <input type="number" placeholder='Age'onChange={e=>setAge(e.target.value)} />
      <input type="text" placeholder="Email"onChange={e=>setEmail(e.target.value)} />
      <button onClick={createUser}>Create User</button>
    </div>

    </div>
  );
}


export default App;
